import hashlib
import hmac
import time
import os
import sqlite3
import threading
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32).hex())
app.config['DATABASE'] = '/tmp/secure_notes.db'

RATE_LIMIT_WINDOW = 60
MAX_REQUESTS = 100

# Thread-safe rate limiter with sliding window
class RateLimiter:
    def __init__(self):
        self._lock = threading.Lock()
        self._requests = {}  # ip -> list of timestamps

    def _cleanup(self, ip, now):
        """Remove expired entries outside the window"""
        if ip in self._requests:
            self._requests[ip] = [
                ts for ts in self._requests[ip]
                if now - ts < RATE_LIMIT_WINDOW
            ]

    def check_rate_limit(self, ip, now=None):
        """Returns (allowed: bool, remaining: int, retry_after: int)"""
        if now is None:
            now = time.time()

        with self._lock:
            self._cleanup(ip, now)

            if ip not in self._requests:
                self._requests[ip] = []

            current_count = len(self._requests[ip])

            # Calculate remaining
            remaining = MAX_REQUESTS - current_count

            if remaining <= 0:
                oldest = min(self._requests[ip]) if self._requests[ip] else now
                retry_after = int(RATE_LIMIT_WINDOW - (now - oldest)) + 1
                return False, 0, max(retry_after, 1)

            self._requests[ip].append(now)
            return True, remaining - 1, 0

rate_limiter = RateLimiter()

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(app.config['DATABASE'])
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        is_admin INTEGER DEFAULT 0
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS notes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        title TEXT NOT NULL,
        content TEXT NOT NULL,
        is_private INTEGER DEFAULT 1,
        created_at REAL DEFAULT (julianday('now')),
        FOREIGN KEY (user_id) REFERENCES users(id)
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS sessions (
        token TEXT PRIMARY KEY,
        user_id INTEGER NOT NULL,
        created_at REAL NOT NULL,
        expires_at REAL NOT NULL,
        revoked INTEGER DEFAULT 0,
        FOREIGN KEY (user_id) REFERENCES users(id)
    )''')
    db.commit()
    db.close()

def hash_password(password, salt=None):
    if salt is None:
        salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + dk.hex()

def verify_password(stored_hash, password):
    parts = stored_hash.split(':')
    if len(parts) != 2:
        return False
    salt = bytes.fromhex(parts[0])
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(dk.hex(), parts[1])

def create_session_token(user_id):
    raw_token = os.urandom(32).hex()
    token_hash = hashlib.sha256(raw_token.encode()).hexdigest()
    expires_at = time.time() + 3600
    db = get_db()
    db.execute(
        'INSERT INTO sessions (token, user_id, created_at, expires_at) VALUES (?, ?, ?, ?)',
        (token_hash, user_id, time.time(), expires_at)
    )
    db.commit()
    return raw_token

def validate_session(raw_token):
    """Validate session token and return user_id if valid"""
    if not raw_token or not isinstance(raw_token, str):
        return None

    # Compute hash of presented token
    token_hash = hashlib.sha256(raw_token.encode()).hexdigest()

    db = get_db()
    session = db.execute(
        'SELECT user_id, expires_at, revoked FROM sessions WHERE token = ?',
        (token_hash,)
    ).fetchone()

    if session is None:
        return None

    # Check expiration and revocation
    if session['revoked']:
        return None

    if time.time() > session['expires_at']:
        # Mark as revoked for cleanup
        db.execute('UPDATE sessions SET revoked = 1 WHERE token = ?', (token_hash,))
        db.commit()
        return None

    return session['user_id']

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing authorization'}), 401

        token = auth_header[7:]
        user_id = validate_session(token)
        if user_id is None:
            return jsonify({'error': 'Invalid or expired session'}), 401

        g.user_id = user_id
        return f(*args, **kwargs)
    return decorated

def require_admin(f):
    @wraps(f)
    @require_auth
    def decorated(*args, **kwargs):
        db = get_db()
        user = db.execute('SELECT is_admin FROM users WHERE id = ?', (g.user_id,)).fetchone()
        if not user or not user['is_admin']:
            return jsonify({'error': 'Admin access required'}), 403
        return f(*args, **kwargs)
    return decorated

@app.before_request
def apply_rate_limit():
    ip = request.remote_addr
    allowed, remaining, retry_after = rate_limiter.check_rate_limit(ip)
    if not allowed:
        response = jsonify({'error': 'Rate limit exceeded'})
        response.status_code = 429
        response.headers['Retry-After'] = str(retry_after)
        return response

@app.route('/api/register', methods=['POST'])
def register():
    data = request.get_json(force=True)
    username = data.get('username', '').strip()
    password = data.get('password', '')

    if not username or len(username) < 3 or len(username) > 32:
        return jsonify({'error': 'Invalid username'}), 400
    if not password or len(password) < 8:
        return jsonify({'error': 'Password too short'}), 400

    password_hash = hash_password(password)
    db = get_db()
    try:
        db.execute('INSERT INTO users (username, password_hash) VALUES (?, ?)',
                   (username, password_hash))
        db.commit()
        return jsonify({'message': 'User created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username taken'}), 409

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json(force=True)
    username = data.get('username', '').strip()
    password = data.get('password', '')

    if not username or not password:
        return jsonify({'error': 'Missing credentials'}), 400

    db = get_db()
    user = db.execute('SELECT id, password_hash FROM users WHERE username = ?',
                      (username,)).fetchone()

    if user is None or not verify_password(user['password_hash'], password):
        return jsonify({'error': 'Invalid credentials'}), 401

    token = create_session_token(user['id'])
    return jsonify({'token': token}), 200

@app.route('/api/notes', methods=['GET'])
@require_auth
def list_notes():
    db = get_db()
    # Users can see their own notes and public notes from others
    notes = db.execute(
        '''SELECT n.id, n.title, n.content, n.is_private, n.created_at, u.username
           FROM notes n JOIN users u ON n.user_id = u.id
           WHERE n.user_id = ? OR n.is_private = 0
           ORDER BY n.created_at DESC''',
        (g.user_id,)
    ).fetchall()
    return jsonify([dict(n) for n in notes])

@app.route('/api/notes', methods=['POST'])
@require_auth
def create_note():
    data = request.get_json(force=True)
    title = data.get('title', '').strip()
    content = data.get('content', '').strip()
    is_private = 1 if data.get('private', True) else 0

    if not title or not content:
        return jsonify({'error': 'Title and content required'}), 400
    if len(title) > 200 or len(content) > 10000:
        return jsonify({'error': 'Content too long'}), 400

    db = get_db()
    cursor = db.execute(
        'INSERT INTO notes (user_id, title, content, is_private) VALUES (?, ?, ?, ?)',
        (g.user_id, title, content, is_private)
    )
    db.commit()
    return jsonify({'id': cursor.lastrowid}), 201

@app.route('/api/notes/<int:note_id>', methods=['GET'])
@require_auth
def get_note(note_id):
    db = get_db()
    note = db.execute(
        'SELECT n.*, u.username FROM notes n JOIN users u ON n.user_id = u.id WHERE n.id = ?',
        (note_id,)
    ).fetchone()

    if note is None:
        return jsonify({'error': 'Note not found'}), 404

    # Access control: owner or public note
    if note['user_id'] != g.user_id and note['is_private']:
        return jsonify({'error': 'Access denied'}), 403

    return jsonify(dict(note))

@app.route('/api/notes/<int:note_id>', methods=['DELETE'])
@require_auth
def delete_note(note_id):
    db = get_db()
    note = db.execute('SELECT user_id FROM notes WHERE id = ?', (note_id,)).fetchone()

    if note is None:
        return jsonify({'error': 'Note not found'}), 404
    if note['user_id'] != g.user_id:
        return jsonify({'error': 'Access denied'}), 403

    db.execute('DELETE FROM notes WHERE id = ?', (note_id,))
    db.commit()
    return jsonify({'message': 'Deleted'}), 200

