@app.route('/api/profile/password', methods=['PUT'])
@require_auth
def change_password():
    data = request.get_json(force=True)
    old_password = data.get('old_password', '')
    new_password = data.get('new_password', '')

    if not new_password or len(new_password) < 8:
        return jsonify({'error': 'New password too short'}), 400

    db = get_db()
    user = db.execute('SELECT password_hash FROM users WHERE id = ?',
                      (g.user_id,)).fetchone()

    if not verify_password(user['password_hash'], old_password):
        return jsonify({'error': 'Current password incorrect'}), 401

    new_hash = hash_password(new_password)
    db.execute('UPDATE users SET password_hash = ? WHERE id = ?',
               (new_hash, g.user_id))
    # Revoke all other sessions
    token_hash = hashlib.sha256(
        request.headers.get('Authorization', '')[7:].encode()
    ).hexdigest()
    db.execute('UPDATE sessions SET revoked = 1 WHERE user_id = ? AND token != ?',
               (g.user_id, token_hash))
    db.commit()
    return jsonify({'message': 'Password changed'}), 200

@app.route('/api/notes/search', methods=['GET'])
@require_auth
def search_notes():
    query = request.args.get('q', '').strip()
    if not query or len(query) < 2:
        return jsonify({'error': 'Query too short'}), 400

    # Escape LIKE wildcards to prevent pattern injection
    escaped_query = query.replace('%', '\\%').replace('_', '\\_')

    db = get_db()
    # Search user's own notes and public notes
    notes = db.execute(
        '''SELECT n.id, n.title, n.content, n.is_private, u.username
           FROM notes n JOIN users u ON n.user_id = u.id
           WHERE (n.user_id = ? OR n.is_private = 0)
           AND (n.title LIKE ? ESCAPE '\\' OR n.content LIKE ? ESCAPE '\\')
           ORDER BY n.created_at DESC LIMIT 50''',
        (g.user_id, f'%{escaped_query}%', f'%{escaped_query}%')
    ).fetchall()
    return jsonify([dict(n) for n in notes])

@app.route('/api/notes/export', methods=['GET'])
@require_auth
def export_notes():
    db = get_db()
    format_type = request.args.get('format', 'json')

    if format_type not in ('json', 'csv'):
        return jsonify({'error': 'Invalid format'}), 400

    notes = db.execute(
        'SELECT id, title, content, is_private, created_at FROM notes WHERE user_id = ?',
        (g.user_id,)
    ).fetchall()

    if format_type == 'csv':
        import csv
        import io
        output = io.StringIO()
        writer = csv.writer(output)
        writer.writerow(['id', 'title', 'content', 'private', 'created_at'])
        for note in notes:
            writer.writerow([note['id'], note['title'], note['content'],
                           note['is_private'], note['created_at']])
        return output.getvalue(), 200, {'Content-Type': 'text/csv'}

    return jsonify([dict(n) for n in notes])

@app.route('/api/notes/share', methods=['POST'])
@require_auth
def share_note():
    data = request.get_json(force=True)
    note_id = data.get('note_id')
    target_username = data.get('username', '').strip()

    if not note_id or not target_username:
        return jsonify({'error': 'Missing parameters'}), 400

    db = get_db()
    note = db.execute('SELECT user_id, is_private FROM notes WHERE id = ?',
                      (note_id,)).fetchone()

    if note is None:
        return jsonify({'error': 'Note not found'}), 404
    if note['user_id'] != g.user_id:
        return jsonify({'error': 'Not your note'}), 403

    # Make the note public so the target user can see it
    db.execute('UPDATE notes SET is_private = 0 WHERE id = ?', (note_id,))
    db.commit()
    return jsonify({'message': f'Note shared (made public)'}), 200

@app.route('/api/logout', methods=['POST'])
@require_auth
def logout():
    token = request.headers.get('Authorization', '')[7:]
    token_hash = hashlib.sha256(token.encode()).hexdigest()
    db = get_db()
    db.execute('UPDATE sessions SET revoked = 1 WHERE token = ?', (token_hash,))
    db.commit()
    return jsonify({'message': 'Logged out'}), 200

